		caPEMs, err = pool.AddCACertificate(caPEMs)
		if errors.Is(err, ErrExpired) {
			warnings = append(warnings, err)
		} else if errors.Is(err, ErrInvalidPEMCertificateUnsupported) {
			warnings = append(warnings, err)
		} else if err != nil {
			return nil, warnings, err
